delete from public.boarding_events where trip_id in (
  select t.id from public.trips t
  join public.buses b on b.id = t.bus_id
  where b.school_id = 'a0000000-0000-4000-8000-000000000001'
);
delete from public.trips where bus_id in (
  select id from public.buses where school_id = 'a0000000-0000-4000-8000-000000000001'
);
